    defected_weighted = 0.0
    total_weight = 0.0
    for i, entry in enumerate(recent_history):
        if entry['role'] == 'recipient':
            age = len(recent_history) - i
            recency_weight = 0.9 ** age  # stronger decay than original
            if entry['partner_action'] == 'donate':
                donated_weighted += recency_weight
