def decide(recipient_reputation, round_num, my_history):
    # More lenient reputation threshold: cooperate with anyone not clearly bad.
    if recipient_reputation > -0.1:
        return True
    # Defect only if reputation is very low.
    elif recipient_reputation < -0.3:
        return False
    # For ambiguous reputations, use a simple majority of recent interactions
    # where this agent was the recipient (no recency decay).
    recent_history = my_history[-10:] if len(my_history) >= 10 else my_history
    donations = 0
    defections = 0
    for entry in recent_history:
        if entry['role'] == 'recipient':
            if entry['partner_action'] == 'donate':
                donations += 1
            else:
                defections += 1
    # If no relevant history, default to defect.
    if donations == 0 and defections == 0:
        return False
    # Donate only if the recipient has donated more often than not.
    return donations > defections
